// Why this workflow exists
// -------------------------
// The Supabase free tier pauses a project after roughly 7 days with no
// activity. It happened: 25 idle days took the platform DB down, and
// Checkpoint A could not start until it was restored by hand.
//
// Nothing we already had would have told us. backup.sh only dumps the ENGINE
// Postgres on our own server, so the nightly log stays green -- exit 0, dump
// written, pushed -- while the platform DB is unreachable. A green backup log
// is not a Supabase health signal and must never be read as one.
//
// So this does two jobs at once: the daily read keeps the idle timer from ever
// reaching 7 days, and a failed read is the signal that something is wrong.
//
// It THROWS on failure rather than returning cleanly, because a thrown error is
// what makes n8n record a failed execution. A workflow that quietly returns
// {ok:false} looks identical to a healthy one in the executions list.

const res = $input.first().json;
const code = res.statusCode;
const ok = code >= 200 && code < 300;

if (ok) {
  return [{ json: { ok: true, statusCode: code, checkedAt: new Date().toISOString() } }];
}

// Deliberately not written to Supabase: it is the thing that is down.
const detail = typeof res.body === 'string' ? res.body.slice(0, 300) : JSON.stringify(res.body || {}).slice(0, 300);
throw new Error(
  'SUPABASE KEEPALIVE FAILED -- platform DB unreachable. ' +
  'statusCode=' + code + '. ' +
  'Most likely the free-tier project has auto-paused (7 days idle) or the ' +
  'service_role key has been rotated. Check the Supabase dashboard first. ' +
  'Detail: ' + detail
);
